<template>
	<d2-container>
		<div>
			<div v-if="nowView === 1">
				<div>
					<vxe-grid v-bind="gridOptions" :highlight-current-row="true" header-align="center" :data="tableData"
						:columns="col" ref="tjb">
						<template #form>
							<vxe-form :data="formData" @submit="searchEvent2" :rules="rules">
								<vxe-form-item title="统计类型" span="5">
									<template #default="{ data }">
										<vxe-select v-model="data.djlx" placeholder="请选择" disabled clearable
											@clear="qclx">
											<!-- <vxe-option value="订单" label="采购统计"></vxe-option> -->
											<vxe-option value="出库查询" label="销售统计"></vxe-option>
										</vxe-select>
									</template>
								</vxe-form-item>
								<vxe-form-item title="分组设置" span="5">
									<template #default="{ data }">
										<vxe-select v-model="data.tjfz" placeholder="请选择" clearable @clear="qcfz">
											<vxe-option value="产品" label="产品"></vxe-option>
											<vxe-option value="业务员" label="业务员"></vxe-option>
										</vxe-select>
									</template>
								</vxe-form-item>
								<vxe-form-item title="年份设置" span="5">
									<template #default="{ data }">
										<vxe-input v-model="data.nf" placeholder="当月请点执行" type="month"
											clearable></vxe-input>
									</template>
								</vxe-form-item>
								<vxe-form-item>
									<template #default>
										<vxe-button status="primary" type="submit">执行统计</vxe-button>
									</template>
								</vxe-form-item>
								<vxe-form-item>
									<template #default>
										<el-button type="info" icon="el-icon-download" size="medium"
											@click="exportDataEvent">导出</el-button>
									</template>
								</vxe-form-item>
							</vxe-form>
						</template>
						<template #num1_default="{ row }">
							<span>{{ row }}</span>
						</template>
						<template #pager>
							<vxe-pager
								:layouts="['Sizes', 'PrevJump', 'PrevPage', 'Number', 'NextPage', 'NextJump', 'FullJump', 'Total']"
								:current-page.sync="tablePage.currentPage" :page-size.sync="tablePage.pageSize"
								:total="tablePage.totalResult" @page-change="handlePageChange">
							</vxe-pager>
						</template>
					</vxe-grid>
					<div class="echart1" ref="echart1" style="margin-top:10Px"></div>

				</div>




			</div>
		</div>
	</d2-container>

</template>
<script>
// echart官方的动态引入	
require("echarts/lib/component/legend");
require('echarts/lib/component/tooltip')
require('echarts/lib/component/title')
require('echarts/lib/chart/bar') // 引入柱状图组件
require("echarts/lib/chart/line"); //引入折线图
require("echarts/lib/chart/pie"); //引入饼图
require("echarts/lib/chart/radar"); //引入雷达
require("echarts/lib/chart/gauge"); //引入仪表图
require("echarts/lib/chart/scatter"); //引入散点图 
let echarts = require('echarts/lib/echarts')

import jsbarcode from 'jsbarcode'
import printJS from 'print-js'
import { mapState, mapActions } from 'vuex'
import setter from '@/libs/setter.js'
//import Print from './plugin/print/Print'
import {
	GetMenuTreeOnAuth,
} from '@api/sys.login.js'
import {
	Query,
	Aud,
	Tongji
} from '@api/shuju.js'

export default {
	name: 'aytj',
	components: {

	},
	data() {
		return {
			fullscreenLoading: false,
			nowView: 1, //当前视图：1是列表，2是编辑页面
			authKeys: [], //用户的权限数组
			tableHeight: 0, //表格高度
			tableData: [], //表内数据	相当于layuidata	
			childData: [],	//子表数据	相当于soulTable子表		
			loading: false, //是否显示加载中
			tablePage: { // 分页属性---
				currentPage: 1, //当前页 相当于layui的page
				pageSize: 10,  	//每页条数 相当于layui的limt
				totalResult: 0  //总页数   相当于count				
			},
			list: [],
			col: [],
			isShow: true,
			TFList: [{
				label: '是',
				value: true
			},
			{
				label: '否',
				value: false
			}
			],
			path: '',
			gnqx: [],
			riqi: '',
			uname: '',
			khList: [],
			cpList: [],
			//搜索变量
			searchFilter: {
				name: '',
				//account: '',
				disable: ''
			},
			formData: {
				djlx: '出库查询',
				tjfz: '产品',
				nf: '',
			},
			form: {
				hwhm: '',
				kfmc: '',
				id: '',
				hwqz: '',
				hwhs: '',
				hwls: ''
			},
			echartBtn: ['柱状图'],
			xz: false,
			xg: false,
			formLabelWidth: '120px',
			disables: [{
				'value': '是'
			}, {
				'value': '否'
			}],

			dialogTableVisible: false,
			dialogVisible: false,
			dialogVisible2: false,
			passID: null,
			rules: {
				tjfz: [
					{ required: true, message: '请输入行数', trigger: 'blur' },
					// { type: 'number', message: '行数必须为数字值'}
				],
				djlx: [
					{ required: true, message: '请输入列数', trigger: 'blur' },
					// { type: 'number', message: '列数必须为数字值'}
				],
			},
			gridOptions: {
				border: true,
				//stripe: true,
				resizable: true,
				height: 0,
				// 分组列头，通过 children 定义子列
				col: [],
				tableData: [],

			}

		}

	},
	created() {
		//this.getAuthKeys()
		this.getcpData()
		this.getkhData()
		this.findList()

		//this.getTableData()

	},
	mounted() {
		this.autoTableHeight()
	},

	methods: {



		//表格根据浏览器调整高度---

		autoTableHeight() {
			this.tableHeight = window.innerHeight - 235;
			this.gridOptions.height = window.innerHeight - 135;
			window.onresize = () => {
				return (() => {
					this.tableHeight = window.innerHeight - 235;
					this.gridOptions.height = window.innerHeight - 135;
				})();
			};

		},
		qcfz() {
			this.formData.tjfz = ''
		},
		qclx() {
			this.formData.djlx = ''
		},
		findList() {
			this.loading = true
			setTimeout(() => {
				let sj = this.list
				this.loading = false
				this.tablePage.totalResult = sj.length
				this.tableData = sj.slice((this.tablePage.currentPage - 1) * this.tablePage.pageSize, this.tablePage.currentPage * this.tablePage.pageSize)
				console.log(this.tableData)
			}, 300)
		},

		getkhData() {

			Query({
				tj: true,
				tablename: '客户',
				field: 'id'
			})
				.then(res => {
					this.khList = res.data
				})
				.catch(err => {
					// 异常情况

				})
		},
		getcpData() {
			Query({
				tj: true,
				tablename: '产品',
				field: 'id'
			})
				.then(res => {
					this.cpList = res.data
				})
				.catch(err => {
					// 异常情况

				})
		},
		getAuthKeys() {
			let sj = JSON.parse(window.localStorage.getItem('d2admin-1.7.2'))
			let info = sj.sys.user.用户.user.info
			if (info.name == 'admin') {
				let qx;
				Query({
					tablename: '菜单',
					columns: '二级菜单',
					field: 'id',
					tj: true,
				})
					.then(resl => {
						qx = resl.map(function (v,) {
							return v.二级菜单
						})
						console.log(qx);
						this.authKeys = qx
						this.getTableData()
						this.uname = info.name
					}).catch(err => { })
			} else {
				GetMenuTreeOnAuth({
					username: info.name
				})
					.then(res => {
						this.authKeys = res.功能权限
						console.log(this.authKeys);
						this.getTableData()
						this.uname = info.name

					})
					.catch(err => { })
			}
		},
		searchEvent2() {

			// this.getTableData()
			this.handleSearch()
		},
		getTableData() {
			let tj
			let xid
			let xmc
			let ymc
			let qt
			let xt
			let yid


			if (this.formData.tjfz != '' && this.formData.djlx != '') {
				let fz = this.formData.tjfz;
				if (fz == '产品') {
					xid = '产品ID';
					xmc = '产品名称';
					yid = '业务员';
					ymc = '业务员';
					qt = this.khList
					xt = this.cpList
				} else if (fz == '业务员') {
					xid = '业务员';
					xmc = '业务员';
					yid = '产品ID';
					ymc = '产品名称';
					qt = this.cpList
					xt = this.khList
				}
				let col = [
					{ type: 'seq', width: 50, title: '序号' },
					{ field: xmc, title: xmc },

				]

				this.loading = true
				if (this.formData.nf) {
					let ns = this.formData.nf.split('-')
					// tj = `DATE_FORMAT(日期, '%Y%m')= ${ns[0]+ns[1]} `;//mysql
					tj = `strftime('%Y%m', 日期) = '${ns[0] + ns[1]}'`;//sqlite

				} else {
					//tj = `MONTH(${this.formData.djlx}.日期) =  MONTH(CURDATE()) `;//mysql
					tj = `strftime('%Y%m', 日期) =  strftime('%Y%m', 'now')`;//sqlite
				}
				//console.log(tj)
				Query({   //按年搜索
					tj: tj,
					tablename: this.formData.djlx,
					columns: `${yid}`,
				})
					.then(res => {
						if (res.length > 0) {							
							let list = res.filter((v)=>{
                              if(v[yid] != null ){
								return v
							  }
							})
							let bt = list.map(item => {
								if (yid == '产品ID') {
									let obj22 = qt.find(o => o[yid] === item[yid]);
									return {
										title: obj22[ymc],
										children: [
											{ field: item[yid], title: '数量' },
											{ field: item[yid] + '金额', title: '金额' }
										]
									}
								} else {
									
										return {
										title: item[yid],
										children: [
											{ field: item[yid], title: '数量' },
											{ field: item[yid] + '金额', title: '金额' }
										]
									}
									
									
								}
							})
							let arr = [...col, ...bt]
							arr.push(
								{
									title: '合计',
									children: [
										{ field: '合计', title: '数量' },
										{ field: '总金额', title: '总金额' }
									]
								})
							console.log(arr)
							this.col = arr
							let hg = res.map(function (ite) {
								if(ite[yid] != null){
                                   // return `SUM(IF(${yid}='${ite[yid]}',数量,0)) AS ${ite[yid]}`;//mysql
								return `SUM(CASE WHEN ${yid}='${ite[yid]}' THEN 数量 ELSE 0 END) AS ${ite[yid]}`
								}
								
							});
							hg = hg.filter(Boolean)
							console.log(hg)
							let hg2 = res.map(function (ite2) {
								if(ite2[yid] != null){
                                 //return `SUM(IF(${yid}='${ite2[yid]}',金额,0)) AS ${ite2[yid] + '金额'}`; //mysql
								return `SUM(CASE WHEN ${yid}='${ite2[yid]}' THEN 数量 ELSE 0 END) AS ${ite2[yid] + '金额'}`
								}
								
							});
							hg2 = hg2.filter(Boolean)
							console.log(hg2)
							let count = `SELECT  IFNULL(${yid}, 'total') AS ${yid},${xid},${hg},${hg2}, SUM(数量) AS 合计,SUM(金额) AS 总金额 FROM 出库查询 WHERE ${tj} GROUP BY ${yid} HAVING ${yid} IS NOT NULL OR ${yid} = 'total'`;
							if (hg && hg2) {

								Tongji({     //sql 统计数据
									// reqType: 'cross',
									// group: xid,
									// tablename: this.formData.djlx,
									// hgroup: hg + ',' + '' + hg2,
									// hj: `SUM(数量) AS 合计,SUM(金额) AS 总金额`,
									// tj: tj
									reqType: 'count',
									group: xid,
									count: count,
								})
									.then(res2 => {
										console.log(res2)
										let obj
										let mc = []
										let tbsj = []
										let nsj = res2.data.map(v => {
											if (v[xid] != 'total') {
												if (xid == '产品ID') {
													let obj4 = xt.find(o => o[xid] === v[xid]);
													console.log(obj4)
													obj = { [xmc]: obj4[xmc] }
													console.log(obj)
													tbsj.push({
														value: v.合计,
														name: obj4[xmc]
													})
													mc.push(obj4[xmc])
													console.log(mc)
												} else {
													obj = { [xid]: v[xid] }
													console.log(obj)
													tbsj.push({
														value: v.合计,
														name: v[xid]
													})
													mc.push(v[xid])
													console.log(mc)
												}
											} else {

												obj = { [xmc]: '合计' }
											}

											return Object.assign(v, obj);
										})

										console.log(tbsj)
										console.log(mc)
										console.log(nsj)
										this.list = nsj
										this.getEchart(tbsj, mc)
									})
									.catch(err => {
										// 异常情况
										this.loading = false
									})
							}
							this.loading = false
						} else {
							this.$message.warning('选择的月份没有数据')
						}
					})
					.catch(err => {
						// 异常情况
						this.loading = false
					})
			} else {
				this.$message.error('请选择统计类型和分组设置')

			}

		},
		getEchart(data, arr) {
			//柱状图 示例
			var _this = this;
			let option;
			let xsz = setter.getTime().split(' ');
			let xs = xsz[0].split('-');
			/*Tongji({
				reqType:'group',
				group:'产品ID',
				tablename:'订单',
				//tj:`DATE_FORMAT(日期, '%Y%m')='${xs[0]+xs[1]}'`
				tj:`DATE_FORMAT(日期, '%Y%m')='202109'`
			}) 
			.then(result => {
			let	zongl = result.data.map(function(v,i){
					 return   v.总量

				})
			let	zongj = result.data.map(function(v,i){
					 return   v.总金额
			
				})
			setTimeout(function(){
			let	cpid = result.data.map(function(v,i){			
				let obj23 = _this.cpList.find(o => o.产品ID === v.产品ID);
					 return   obj23.产品名称
				   
				}) 
				
			option ={ 
			  title: {
			  text: '销售统计',
				   },
			tooltip: {
		   trigger: 'axis',
		   axisPointer: {
			type: 'cross',
		   crossStyle: {
		  color: '#999'
			   }
					  }
			}, 
	 legend: {
	   data: ['总量', '总金额']
	 },
   xAxis: [{
	type: 'category',
	data: cpid ,
	axisPointer: {
		type: 'shadow'
		}
	  }],
	  yAxis: [{}],
	  series: [{
				  name: "总量",
				  type: 'bar',
				  data: zongl
				}, {
				  name: "总金额",
				  type: 'bar',
				  data: zongj 
				}]
	  } 
	},200)		
		    
			}).catch(err => {})*/
			option = {
				title: {
					text: '统计图表',
					subtext: '月度统计',
					left: 'center'
				},
				tooltip: {
					trigger: 'item',
					formatter: '{a} <br/>{b} : {c} ({d}%)'
				},
				legend: {
					orient: 'vertical',
					left: 'left',
					data: arr
				},
				series: [{
					name: '数量',
					type: 'pie',
					radius: '55%',
					center: ['50%', '60%'],
					data: data,
					emphasis: {
						itemStyle: {
							shadowBlur: 10,
							shadowOffsetX: 0,
							shadowColor: 'rgba(0, 0, 0, 0.5)'
						}
					}
				}]
			}
			setTimeout(function () {
				// 基于准备好的dom，初始化echarts实例				
				let myChart = echarts.init(_this.$refs.echart1)
				myChart.setOption(option, true) //true表示数据不合并
				//option && myChart.setOption(option);
				window.onresize = myChart.resize //让图表自动宽度
			}, 200)

		},
		xzsj() {
			let sj = this.$refs.xTable1.getCheckboxRecords()
			console.log(this.$refs.xTable1.getCheckboxRecords())
			this.$refs.xTable1.insertAt(sj, -1)
		},
		handleSearch() {
			this.loading = true
			this.tablePage.currentPage = 1 //注意要回来第一页
			this.findList()
			this.getTableData()
		},
		handlePageChange({
			currentPage,
			pageSize
		}) {
			this.tablePage.currentPage = currentPage
			this.tablePage.pageSize = pageSize
			this.findList()
			this.getTableData()
		},
		clearFilter() {
			let obj = this.searchFilter
			for (let key in obj) {
				this.searchFilter
				obj[key] = null
			}
		},

		exportDataEvent() {
			this.$refs.tjb.exportData({
				type: 'csv',
				isHeader: true,
				isHeader: true
			})
		},
		goToAdd() {
			this.dialogVisible = true
			this.xz = true
			this.xg = false
			/* const $grid = this.$refs.xTable1
		  $grid.insert({}) */
		},
		goToAdd2() {
			this.dialogVisible2 = true
			//this.xz = true
			//this.xg = false
			/* const $grid = this.$refs.xTable1
		  $grid.insert({}) */
		},
		goToEdit(row) {
			console.log(row)
			this.dialogVisible = true
			this.xg = true
			this.xz = false
			this.form.hwhm = row.货位号
			this.form.id = row.id
		},
		onSubmit() {

			Aud({     //后台数据提交
				reqType: 'append',
				content: [{
					货位号: this.form.hwhm,
				}],
				tablename: '货位',
				//order : 'desc'
			})
				.then(result31 => {
					this.getTableData()
					this.form.hwhm = ''
					this.form.id = ''
					this.$message.success('货位已增加')

				}).catch(err => {
					//this.fullscreenLoading = false
				})

			this.dialogVisible = false
		},
		onSubmit2() {

			Aud({
				reqType: 'update',
				content: [{
					货位号: this.form.hwhm,
					id: this.form.id,
				}],
				tablename: '货位'

			})
				.then(res => {
					this.getTableData()
					this.form.hwhm = ''
					this.form.id = ''
					this.$message.success('货位修改成功')
				})
				.catch(err => { })

			this.dialogVisible = false
		},
		Submit22() {
			let hsz = []
			let hlz = []
			let hs
			let hl
			let hwbh = []
			if (this.form.hwhs != '' && this.form.hwls != '') {
				for (let i = 0; i < this.form.hwhs; i++) {
					if (i < 9) {
						hs = '0' + (i + 1).toString()
					} else {
						hs = (i + 1).toString()
					}
					//console.log(hs)
					hsz.push(hs)

				}
				for (let ix = 0; ix < this.form.hwls; ix++) {
					if (ix < 9) {
						hl = '0' + (ix + 1).toString()
					} else {
						hl = (ix + 1).toString()
					}
					//console.log(hl)
					hlz.push(hl)

				}
				hsz.forEach(v => {
					hlz.forEach(val => {
						if (this.form.hwqz != '') {
							hwbh.push({ 货位号: this.form.hwqz + v + val })
						} else {
							hwbh.push({ 货位号: v + val })
						}
					})
				})
				console.log(hwbh)
				this.fullscreenLoading = true
				Aud({     //后台数据提交
					reqType: 'append',
					content: hwbh,
					tablename: '货位',
					//order : 'desc'
				})
					.then(result31 => {
						this.fullscreenLoading = false
						this.form.hwhs = ''
						this.form.hwls = ''
						this.form.hwqz = ''
						this.$message.success('货位已增加')
						this.dialogVisible2 = false
					}).catch(err => {
						this.fullscreenLoading = false
					})

				//this.dialogVisible2 = false
			} else {
				this.$message.warning('请输入货位行数和货位列数')
			}

		},
		//用户删除
		deletehw() {
			let selectRecords = this.$refs.xTable1.getCheckboxRecords()
			let tempIDs = []
			for (let i = 0; i < selectRecords.length; i++) {
				let sr = selectRecords[i]
				tempIDs.push(sr.id)
				console.log(tempIDs)
			}
			if (tempIDs.length > 0) {
				this.$confirm('确定要永久删除这' + tempIDs.length + '行?', '提示', {
					confirmButtonText: '确定',
					cancelButtonText: '取消',
					type: 'warning'
				}).then(() => {
					this.fullscreenLoading = true
					Aud({
						//id: tempIDs.join(',')
						reqType: 'delete',
						content: tempIDs,
						tablename: '货位'
					})
						.then(res => {
							this.fullscreenLoading = false
							this.getTableData()
							this.$message.success('删除成功')
						})
						.catch(err => {
							this.fullscreenLoading = false
						})
				}).catch(() => { });
			} else {
				this.$message.warning('请先勾选要删除的行')
			}
		},

		djdy() {
			const printStyle = `
              .bar-code {
                display: inline-block;
                width: 100%;
                height: 140px;
                float: left;
                text-align: center;
              }
              `
			// 打印模板
			const printTmpls = []
			let dysj = this.$refs.xTable1.getCheckboxRecords()
			let tempIDs = []
			for (let i = 0; i < dysj.length; i++) {
				let sr = dysj[i]
				tempIDs.push(sr.id)
				console.log(tempIDs)
			}
			if (tempIDs.length > 0) {


				dysj.forEach(item => {
					const img = document.createElement('img')
					// 生成条形码
					jsbarcode(img, item.货位号, {
						lineColor: '#000',
						width: 2,
						height: 80,
						displayValue: true
					})
					const tmpl = `
                <div class="bar-code">                 
                  ${img.outerHTML}
                </div>
                `
					printTmpls.push(tmpl)
				})
				this.$XPrint({
					sheetName: '货位条形码',
					style: printStyle,
					content: printTmpls.join('')
				})
			} else {
				this.$message.warning('请先勾选要打印的行')
			}


		},

		closeCopyDialog() {
			this.$refs.authForm.resetFields();
			this.authCopy.dialogVisible = false
		},

		formatterTF({
			cellValue
		}) {
			let item = this.TFList.find(item => item.value === cellValue)
			return item ? item.label : ''
		},

		//是否智能下拉---
		querySearch(queryString, cb) {
			let values = this.disables; //传入下拉列表数组
			let results = queryString ? values.filter(this.createFilter(queryString)) : values;
			// 调用 callback 返回建议列表的数据
			cb(results);
		},
		createFilter(queryString) {
			return (e) => {
				return (e.value.toLowerCase().indexOf(queryString.toLowerCase()) === 0);
			}
		},
		//是否智能下拉---



		printEvent1() {
			this.$print(this.$refs.print)
			this.dialogTableVisible = false
		},

	},



}

</script>

